const float b2[1] = {0.4334696829319f};

#define NY_MODEL 15
#define NU_MODEL 15
static float sil_y_hist[NY_MODEL] = {0};
static float sil_u_hist[NU_MODEL] = {0};

static float simulate_narx(float u_atual) {
    for (int i = NU_MODEL - 1; i > 0; i--) sil_u_hist[i] = sil_u_hist[i-1];
    sil_u_hist[0] = u_atual;

    float y_k = 1.4230142041509461f * (sil_y_hist[0])
              + -0.211981152274884f * (sil_y_hist[1])
              + 0.03884515207142053f * (sil_y_hist[14])
              + -0.15684784770597934f * (sil_y_hist[3])
              + -9.329492773929156e-07f * (sil_u_hist[2] * sil_u_hist[5])
              + 6.910645291827972e-06f * (sil_y_hist[0] * sil_y_hist[0])
              + -0.09444725816635065f * (sil_y_hist[9])
              + 1.7679153728457313e-05f * (sil_u_hist[5] * sil_u_hist[8])
              + -0.005892272527567124f * 1.0f
              + 9.312745501841735e-06f * (sil_u_hist[2] * sil_u_hist[14]);

    for (int i = NY_MODEL - 1; i > 0; i--) sil_y_hist[i] = sil_y_hist[i-1];
    sil_y_hist[0] = y_k;
    return y_k;
}

static inline float relu(float x) { return (x > 0.0f) ? x : 0.0f; }

static float ann_predict(float *input) {
    float h1[128] = {0};
    float h2[128] = {0};
    float out = 0.0f;

    float norm_input[80];
    for (int i = 0; i < 80; i++) {
        norm_input[i] = (input[i] - scaler_mean[i]) / scaler_scale[i];
    }

    for (int i = 0; i < 128; i++) {
        float sum = b0[i];
        for (int j = 0; j < 80; j++) {
            sum += W0[i * 80 + j] * norm_input[j];
        }
        h1[i] = relu(sum);
    }

    for (int i = 0; i < 128; i++) {
        float sum = b1[i];
        for (int j = 0; j < 128; j++) {
            sum += W1[i * 128 + j] * h1[j];
        }
        h2[i] = relu(sum);
    }

    out = b2[0];
    for (int i = 0; i < 128; i++) {
        out += W2[i] * h2[i];
    }

    if (out > 80.0f) out = 80.0f;
    if (out < -10.0f) out = -10.0f;
    return out;
}

